@namespace sv_2766e05c2deb45fb8332f3fb51ac432a.Components.Pages.Settings

<nav class="settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            @section
        </button>
    }
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };
}

@namespace sv_2766e05c2deb45fb8332f3fb51ac432a.Components.Pages.Settings

<div class="settings-section">
    <h2>Profile</h2>

    <div class="avatar-preview">
        @if (!string.IsNullOrEmpty(DisplayName))
        {
            <img src="@AvatarUrl" alt="Avatar" class="avatar-image" />
        }
        <p class="avatar-url">@AvatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="DisplayName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="Bio" @bind:event="oninput" rows="4"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="Save">Save Changes</button>
        <button class="btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (ShowSuccess)
    {
        <div class="toast success">Profile saved successfully!</div>
    }
</div>

@code {
    [Parameter] public string DisplayName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Bio { get; set; } = "";
    [Parameter] public string AvatarUrl { get; set; } = "";
    [Parameter] public EventCallback<(string DisplayName, string Email, string Bio)> OnSave { get; set; }
    [Parameter] public EventCallback OnDiscard { get; set; }

    private bool ShowSuccess;

    private async Task Save()
    {
        await OnSave.InvokeAsync((DisplayName, Email, Bio));
        ShowSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private async Task Discard()
    {
        await OnDiscard.InvokeAsync();
    }
}

@namespace sv_2766e05c2deb45fb8332f3fb51ac432a.Components.Pages.Settings

<div class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="EmailNotifications" />
            <span>Email Notifications</span>
        </label>

        <label class="toggle-label">
            <input type="checkbox" @bind="PushNotifications" />
            <span>Push Notifications</span>
        </label>

        <label class="toggle-label">
            <input type="checkbox" @bind="WeeklyDigest" />
            <span>Weekly Digest</span>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in AllChannels)
        {
            var isMuted = MutedChannels.Contains(channel);
            <label class="toggle-label">
                <input type="checkbox" checked="@isMuted"
                       @onchange="(e) => ToggleChannel(channel, (bool)e.Value!)" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="Save">Save Preferences</button>
    </div>
</div>

@code {
    [Parameter] public bool EmailNotifications { get; set; }
    [Parameter] public bool PushNotifications { get; set; }
    [Parameter] public bool WeeklyDigest { get; set; }
    [Parameter] public List<string> MutedChannels { get; set; } = new();
    [Parameter] public List<string> AllChannels { get; set; } = new();
    [Parameter] public EventCallback<(bool Email, bool Push, bool Digest, List<string> Muted)> OnSave { get; set; }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task Save()
    {
        await OnSave.InvokeAsync((EmailNotifications, PushNotifications, WeeklyDigest, MutedChannels));
    }
}

